"use client";
import "./styles/skeuo-switch.css";


import type { ButtonHTMLAttributes } from "react";

export type SkeuoSwitchProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> & {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
};

/** Controlled switch; provide an accessible label or aria-labelledby. */
export function SkeuoSwitch({ checked, onCheckedChange, className = "", onClick, ...props }: SkeuoSwitchProps) {
  return <button data-sk-root="" {...props} type="button" className={`sk-switch ${className}`} role="switch" aria-checked={checked} onClick={event => { onClick?.(event); if (!event.defaultPrevented) onCheckedChange(!checked); }}><span><i /><i /><i /></span></button>;
}

@import "./skeuo-base.css";
.sk-switch{ width: 49px; height: 28px; border: 1px solid var(--sk-edge); background: var(--sk-well); box-shadow: inset 0 2px 4px var(--sk-shadow), 0 1px 0 var(--sk-highlight); border-radius: 20px; padding: 3px; flex-shrink: 0; transition: background .2s; }
.sk-switch > span{ display: block; width: 20px; height: 20px; border-radius: 50%; background: linear-gradient(150deg,#fff,#deded9); border: 1px solid #ffffff8a; box-shadow: 0 2px 3px #00000035,inset 0 -1px 1px #00000012; transition: transform .22s cubic-bezier(.2,.8,.2,1); }
.sk-switch[aria-checked="true"]{ background: var(--sk-accent); border-color: #9c421d; }
.sk-switch[aria-checked="true"] > span{ transform: translateX(20px); }
.sk-switch[aria-checked="true"]{ border-color: var(--sk-accent-edge); }
.sk-switch:disabled{ opacity: .5; cursor: not-allowed; }
.sk-switch{position:relative;width:72px;height:37px;padding:4px;border:1px solid var(--sk-key-edge);border-radius:8px;flex-shrink:0;background:var(--sk-well);box-shadow:inset 0 4px 7px #00000055,inset 1px 1px 3px var(--sk-shadow),0 1px var(--sk-highlight),0 3px var(--sk-base),0 4px var(--sk-edge);}
.sk-switch[aria-checked="true"]{background:color-mix(in srgb,var(--sk-accent) 48%,var(--sk-well));}
.sk-switch > span{display:flex;align-items:center;justify-content:center;gap:3px;position:absolute;left:4px;top:3px;width:31px;height:27px;margin:0;border:1px solid var(--sk-key-edge);border-radius:5px;background:linear-gradient(135deg,var(--sk-surface-raised),var(--sk-base));box-shadow:inset 0 2px var(--sk-highlight),inset 0 -2px var(--sk-base),0 3px var(--sk-key-base),0 4px var(--sk-edge),0 5px 4px #00000055;transition:transform .3s cubic-bezier(.2,.7,.25,1);}
.sk-switch[aria-checked="true"] > span{transform:translateX(31px);}
.sk-switch > span i{width:1px;height:11px;background:var(--sk-edge);box-shadow:1px 0 var(--sk-highlight);}
.sk-switch:active > span{top:5px;box-shadow:inset 0 1px var(--sk-highlight),0 1px var(--sk-key-base),0 2px var(--sk-edge);}
@media(prefers-reduced-motion:reduce){.sk-switch > span{transition:none;}}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root] :focus-visible) {outline:2px solid var(--sk-accent);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Namespaced defaults. Host applications can override any --sk-* token. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper:#faf9f5;--sk-album-ink:#45423b;--sk-album-edge:#c4c2ba;--sk-album-base:#d6d4ca;
  --sk-bg: #fff; --sk-ink: #202020; --sk-muted: #777774; --sk-line: #e7e7e4;
  --sk-surface: #f5f5f2; --sk-surface-raised: #fafaf8; --sk-well: #e9e9e5;
  --sk-edge: #d1d1cb; --sk-highlight: #fff; --sk-base: #d9d9d3; --sk-shadow: #00000017;
  --sk-accent: #365e50; --sk-accent-bright: #487b68; --sk-accent-base: #213c32; --sk-accent-edge: #294b3e; --sk-accent-ink: #fff;
  --sk-key: #f9f9f7; --sk-key-edge: #c6c7c1; --sk-key-base: #d0d1ca;
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper:#272728;--sk-album-ink:#d0cfca;--sk-album-edge:#555456;--sk-album-base:#111214;
  --sk-bg: #000; --sk-ink: #efefeb; --sk-muted: #92928d; --sk-line: #242424;
  --sk-surface: #191919; --sk-surface-raised: #252525; --sk-well: #111;
  --sk-edge: #3b3b39; --sk-highlight: #ffffff1e; --sk-base: #080808; --sk-shadow: #00000099;
  --sk-accent: #9ab5a6; --sk-accent-bright: #bbcec2; --sk-accent-base: #4d6558; --sk-accent-edge: #6f8a79; --sk-accent-ink: #14251c;
  --sk-key: #292a29; --sk-key-edge: #484946; --sk-key-base: #101110;

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper:#272728;--sk-album-ink:#d0cfca;--sk-album-edge:#555456;--sk-album-base:#111214;
  --sk-bg: #000; --sk-ink: #efefeb; --sk-muted: #92928d; --sk-line: #242424;
  --sk-surface: #191919; --sk-surface-raised: #252525; --sk-well: #111;
  --sk-edge: #3b3b39; --sk-highlight: #ffffff1e; --sk-base: #080808; --sk-shadow: #00000099;
  --sk-accent: #9ab5a6; --sk-accent-bright: #bbcec2; --sk-accent-base: #4d6558; --sk-accent-edge: #6f8a79; --sk-accent-ink: #14251c;
  --sk-key: #292a29; --sk-key-edge: #484946; --sk-key-base: #101110;

} }
